static int ice_dvm_update_dflt_recipes ( struct ice_hw * hw ) { cfs_time_t i ; for ( i = 0 ; i < ARRAY_SIZE ( ice_dvm_dflt_recipes ) ; i ++ ) { struct ice_update_recipe_lkup_idx_params * params ; int status ; params = & ice_dvm_dflt_recipes [ i ] ; status = ice_update_recipe_lkup_idx ( hw , params ) ; if ( status ) { ice_debug ( hw , ICE_DBG_INIT , "Failed to update RID %d lkup_idx %d fv_idx %d mask_valid %s mask 0x%04x\n" , params -> rid , params -> lkup_idx , params -> fv_idx , params -> mask_valid ?"true" : "false" , params -> mask ) ; return status ; } } return 0 ; } 